def largest_prime_factor(n: int):
    """Return the largest prime factor of n. Assume n > 1 and is not a prime.
    >>> largest_prime_factor(13195)
    29
    >>> largest_prime_factor(2048)
    2
    """
    def is_prime(num):
        """Check if a number is prime."""
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    largest_factor = None
    # Check for number of 2s that divide n
    while n % 2 == 0:
        largest_factor = 2
        n //= 2

    # n must be odd at this point, thus a skip of 2 (i.e., i = i + 2) can be used
    for i in range(3, int(n**0.5) + 1, 2):
        # While i divides n, update n and largest_factor
        while n % i == 0:
            largest_factor = i
            n //= i

    # This condition is to check if n is a prime number greater than 2
    if n > 2:
        largest_factor = n

    return largest_factor

def is_multiply_prime(a):
    """
    Returns True if the given number is the multiplication of 3 prime numbers,
    and False otherwise. The number is less than 100.

    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        """Check if a number is prime."""
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    if a >= 100:
        return False

    primes = [i for i in range(2, 100) if is_prime(i)]
    prime_factors = []

    for prime in primes:
        while a % prime == 0:
            prime_factors.append(prime)
            a //= prime

    return len(prime_factors) == 3 and a == 1

