def next_smallest(lst):
    """
    Returns the 2nd smallest element of the list.
    Returns None if there is no such element.
    """
    if len(lst) < 2:
        return None

    smallest = float('inf')
    second_smallest = float('inf')

    for num in lst:
        if num < smallest:
            second_smallest = smallest
            smallest = num
        elif num < second_smallest and num != smallest:
            second_smallest = num

    return second_smallest if second_smallest != float('inf') else None

def encode(message):
    """
    Encodes a message by swapping the case of all letters and replacing
    vowels with the letter that appears 2 places ahead in the alphabet.

    :param message: The input message to encode.
    :return: The encoded message.
    """
    vowels = 'aeiouAEIOU'
    encoded_message = ''

    for char in message:
        if char.isalpha():
            if char.islower():
                char = char.upper()
            else:
                char = char.lower()

            if char in vowels:
                index = vowels.index(char)
                char = vowels[(index + 2) % len(vowels)]

        encoded_message += char

    return encoded_message

