def intersection(interval1, interval2):
    """Determine if the length of the intersection of two intervals is a prime number."""
    start1, end1 = interval1
    start2, end2 = interval2

    # Calculate the intersection
    intersection_start = max(start1, start2)
    intersection_end = min(end1, end2)

    # Check if there is an intersection
    if intersection_start > intersection_end:
        return "NO"

    # Calculate the length of the intersection
    intersection_length = intersection_end - intersection_start + 1

    # Check if the length is a prime number
    if is_prime(intersection_length):
        return "YES"
    else:
        return "NO"

from typing import List
def minPath(grid: List[List[int]], k: int) -> List[int]:
    """
    Finds the minimum path of length k in the grid.

    :param grid: A 2D list representing the grid.
    :param k: An integer representing the length of the path.
    :return: A list of integers representing the minimum path.
    """
    def dfs(x, y, path, visited):
        if len(path) == k:
            return path
        if x < 0 or x >= len(grid) or y < 0 or y >= len(grid[0]) or (x, y) in visited:
            return None

        visited.add((x, y))
        path.append(grid[x][y])

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            new_path = dfs(x + dx, y + dy, path.copy(), visited.copy())
            if new_path is not None:
                return new_path

        path.pop()
        visited.remove((x, y))
        return None

    min_path = None
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            path = dfs(i, j, [], set())
            if path is not None and (min_path is None or path < min_path):
                min_path = path

    return min_path

def tri(n):
    """
    Calculate the first n + 1 numbers of the Tribonacci sequence.

    Parameters:
    n (int): A non-negative integer representing the number of terms to generate.

    Returns:
    list: A list containing the first n + 1 numbers of the Tribonacci sequence.
    """
    if n < 0:
        raise ValueError("Input must be a non-negative integer")

    if n == 0:
        return [1]
    elif n == 1:
        return [1, 3]
    elif n == 2:
        return [1, 3, 2]

    tribonacci = [1, 3, 2]

    for i in range(3, n + 1):
        if i % 2 == 0:
            tribonacci.append(1 + i / 2)
        else:
            tribonacci.append(tribonacci[i - 1] + tribonacci[i - 2] + tribonacci[i + 1])

    return tribonacci

def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """
    def convert_to_float(x):
        if isinstance(x, str):
            x = x.replace(',', '.')
        return float(x)

    a_float = convert_to_float(a)
    b_float = convert_to_float(b)

    if a_float > b_float:
        return a
    elif b_float > a_float:
        return b
    else:
        return None

def fix_spaces(text):
    """
    Given a string text, replace all spaces in it with underscores, 
    and if a string has more than 2 consecutive spaces, 
    then replace all consecutive spaces with - 

    fix_spaces("Example") == "Example"
    fix_spaces("Example 1") == "Example_1"
    fix_spaces(" Example 2") == "_Example_2"
    fix_spaces(" Example   3") == "_Example-3"
    """
    result = []
    consecutive_spaces = 0

    for char in text:
        if char == ' ':
            consecutive_spaces += 1
        else:
            if consecutive_spaces > 2:
                result.append('-')
            elif consecutive_spaces > 0:
                result.extend(['_'] * consecutive_spaces)
            result.append(char)
            consecutive_spaces = 0

    if consecutive_spaces > 2:
        result.append('-')
    elif consecutive_spaces > 0:
        result.extend(['_'] * consecutive_spaces)

    return ''.join(result)

